function Game.prototype.updateVisuals(self, dt, shakeX, shakeY)
    local view = View.size
    local active = self.mode == "play" or self.mode == "confront" or self.mode == "dialog" or self.mode == "rewind" or self.mode == "dead" or self.mode == "ending"
    if active then
        local tx = clamp(nil, self.player.body.x, view.width / 2, Tower.WORLD_W - view.width / 2)
        local ty = clamp(nil, self.player.body.y + 70, Tower.TOPS[1] + view.height / 2 - 8, Tower.WORLD_H - view.height / 2)
        local k = math.min(1, dt * 6)
        self.camX = self.camX + (tx - self.camX) * k
        self.camY = self.camY + (ty - self.camY) * k
    else
        self.camX = 800
        self.camY = 400
    end
    self.fxDraw.position = Vec2(nil, view.width / 2 - self.camX + shakeX, view.height / 2 - self.camY + shakeY)
    self.npcDraw.position = self.fxDraw.position
    self.sheetNode.position = self.fxDraw.position
    self.fx:update(dt)
    self.sheetFx:update(dt)
    self.fxDraw:clear()
    self.fx:draw(self.fxDraw)
    self.npcDraw:clear()
    if self.mode ~= "title" and self.mode ~= "prologue" then
        self:drawNpcs()
    end
    self.renderer:setWorldVisible(self.mode ~= "title" and self.mode ~= "prologue")
    self.renderer:setCamera(self.camX, self.camY, shakeX, shakeY)
    self.renderer:update(
        dt,
        self.state,
        self.player,
        self.enemies,
        self.mech,
        self.time
    )
    self.hud:update(
        dt,
        {
            state = self.state,
            player = self.player,
            boss = self.enemies:boss(),
            objective = self.state.objective,
            hint = self:hintText(),
            time = self.time
        }
    )
    self.notebook:update(dt, self.state)
end
